namespace PZ3D {
 sealed partial class MainForm {
  string HelpBody(int index){if(index==0)return LauncherQuickHelp+"\r\n\r\n"+ReticleHelp+"\r\n\r\n"+ComponentHelp;if(index==1||index==6)return ReticleHelp+"\r\n\r\n"+ComponentHelp;if(index==2)return "额外 3D 物件模型\r\n\r\n用于将家具、家电、栅栏等平面物件替换成立体模型，不是光影，也不是基础视角的必需项。主页面勾选后点安装，会自动下载缺失内容并启用。\r\n\r\n不需要时，只勾选此项（取消基础 3D、枪械与汉化），点击卸载。基础视角保留，Steam 缓存不删除。取消勾选本身不卸载，需要点击卸载；安装其他组件不会关掉已安装的模型。\r\n\r\n工坊3810302175，原模型作者sour_kisel，兼容性与实际效果以当前作者版本及游戏测试为准。";return HelpContent.Bodies[index-1].Replace("安装 / 启用 3D","安装").Replace("关闭 3D + Buddy","卸载（勾选基础 3D）")+(index==8?LegalContent.OptionalCredits:"");}
  const string LauncherQuickHelp="新版启动器\r\n\r\n左侧主题按钮可在石墨黑金、浅蓝间切换并记忆。首页通过 Steam 正常启动游戏。打开工具只读取本地状态，不自动下载；安装或检查更新才联网。\r\n\r\n组件管理：选择游戏目录并勾选安装/卸载内容。光影列表、Viewpoint中文设置保留游戏设置同步。启动与内存：读取当前Java堆内存与可用RAM，再保存GiB；不修改Windows分页。维护与诊断：一按钮一确认清全部本机已缓存服务器的可重下载地图区块，不备份，保留角色/车辆数据库和未知文件。\r\n\r\n工坊全量重下载保留订阅和其他游戏文件，必须先成功核对在线订阅清单、下载接口与空间。失败或取消后工具内启动被阻止，重新完成重下载后解除；不要绕过工具直接启动未就绪游戏。\r\n\r\n高级与记录：文件改动、备份恢复、诊断、扩展说明和版权。Smooth Frames、KK’s TREE当前缺少完整本地预加载声明，不符合服务器零操作要求，暂不开放安装；工具不改作者JAR。";
  const string ComponentHelp="安装与卸载 · 只用三个按钮\r\n\r\n1. 完全退出游戏。主页面勾选需要的组件，点击“安装”，等待完成后再从 Steam 正常启动。基础 3D/Buddy 会自动作为依赖安装。没有勾选的已安装组件会保留，不会因安装别的组件被卸载。\r\n2. 第一人称枪械瞄准：勾选对应项点“安装”即可，自动处理 Shoot to Thrill 多人版和适用的联机开镜补丁，不用分别点修复、桥接或测试按钮。它不是 GUNS OF MARZ 枪械内容包，不改变服务器枪械或伤害规则。服务器什么都不装的情况下，开镜渲染、瞄具和命中对齐仍需实际测试。\r\n3. 进游戏，核对并批准对应 Java 模组。进服按 O 开启第一人称，右键瞄准，Ctrl+V 切换腰射/精瞄。快捷键以游戏实际绑定为准；有冲突到游戏设置修改。开镜没反应不能只凭安装成功判断，需查看当前游戏日志。\r\n4. 游戏内中文：勾选“游戏内中文（老余汉化）”后点安装。首次从原作者 Steam 工坊下载，版权归老余；工具没有重新打包或改写作者 JAR。游戏语言设为简体中文，核对批准 laoyu.javacn / LaoYuTranslationJava.jar，重启游戏。已存在存档的独立模组列表可能也需启用。此版本作者注明适配 Viewpoint 0.1.6；其他扩展及新版本不能保证全部汉化。服务器内是否保持加载需实测。\r\n5. 卸载：只勾选要撤销的组件，点“卸载”。只卸载枪械时，取消基础 3D、物件模型和汉化勾选；工具会一起撤销枪械及联机开镜补丁。勾选基础 3D 卸载时会连带关闭依赖组件。不会删除 Steam 缓存、光影 ZIP、存档或个人设置。单独卸载物件包保留基础视角。\r\n6. 检查更新：核对所选内容及基础依赖，最新文件不重复下载；未启用的组件不会仅因更新而启用。射击 JAR 更新后，旧开镜补丁可能不能继续使用，工具拒绝强行启用，需更新工具兼容性。模组更新可能重新要求 Java 授权，工具不会代替玩家同意。\r\n\r\n“联机开镜补丁”原来叫“进服开镜恢复桥接”，是本机的初始化补丁，不是服务器安装器，不提供服务器弹道、伤害功能，也不绕过服务器校验。安装已配置不等于本次进服已经生效。失败时会提示部分完成并留下备份；不要盲删游戏或整个模组文件夹。\r\n\r\n作者工坊：汉化 3810637496（老余）；射击 3813032735（haru）；Viewpoint 3809306528（ellu/norkus）；ZombieBuddy 3619862853（原作者）。";
 }
}
